/**
 * Read the provider `<select>` value from the same drawer `getActiveSettingsDrawer` would pick
 * (newest-first among open+visible drawers that expose Connection UI). Uses live DOM `evaluate`, not a
 * cached chained locator, so probes cannot hang on a stale `settings-provider-select` handle.
 */
async function readLiveDrawerScopedProviderValue(pg = page) {
    return pg
        .evaluate(() => {
            const drawerOpenVisible = (d) => {
                if (!(d instanceof Element)) return false;
                if (d.getAttribute('data-state') !== 'open') return false;
                const st = window.getComputedStyle(d);
                const r = d.getBoundingClientRect();
                return (
                    r.width > 0 &&
                    r.height > 0 &&
                    st.display !== 'none' &&
                    st.visibility !== 'hidden' &&
                    Number(st.opacity || '1') > 0
                );
            };
            const pickSelect = (d) => {
                const scoped = d.querySelector(
                    '[data-testid="settings-panel-connection"] [data-testid="settings-connection-controls"] [data-testid="settings-provider-select"]',
                );
                if (scoped instanceof HTMLSelectElement) return scoped;
                const loose = d.querySelector(
                    '[data-testid="settings-connection-controls"] [data-testid="settings-provider-select"]',
                );
                return loose instanceof HTMLSelectElement ? loose : null;
            };
            const drawers = Array.from(document.querySelectorAll('[data-testid="settings-drawer"]'));
            const candidates = drawers.filter(drawerOpenVisible);
            for (let i = candidates.length - 1; i >= 0; i -= 1) {
                const d = candidates[i];
                const hasPanel = d.querySelector('[data-testid="settings-panel-connection"]');
                const hasControls = d.querySelector('[data-testid="settings-connection-controls"]');
                if (!hasPanel && !hasControls) continue;
                const sel = pickSelect(d);
                if (sel) return String(sel.value || '');
            }
            if (candidates.length > 0) {
                const sel = pickSelect(candidates[candidates.length - 1]);
                if (sel) return String(sel.value || '');
            }
            return '';
        })
        .catch(() => '');
}

