                const hasControls = d.querySelector('[data-testid="settings-connection-controls"]');
                if (!hasPanel && !hasControls) continue;
                const tab = d.querySelector('[data-testid="settings-tab-connection"]');
                const panel = d.querySelector('[data-testid="settings-panel-connection"]');
                const ctrl = panel && panel.querySelector('[data-testid="settings-connection-controls"]');
