async function readLiveGoOfflineKillHarnessDom(pg = page) {
    return pg
        .evaluate(() => {
            const pickText = (el) => (el && el.textContent ? el.textContent.trim().slice(0, 200) : '');
            const domGeomVis = (el) => {
                if (!(el instanceof Element)) {
                    return { present: false, domGeometryVisible: false, enabled: false, text: '' };
                }
                const r = el.getBoundingClientRect();
                const st = window.getComputedStyle(el);
                const vis =
                    r.width > 0 &&
                    r.height > 0 &&
                    st.display !== 'none' &&
                    st.visibility !== 'hidden' &&
                    Number(st.opacity || '1') > 0;
                return {
                    present: true,
                    domGeometryVisible: vis,
                    enabled: !el.disabled,
                    text: pickText(el),
                };
            };
            const drawerOpenVisible = (d) => {
                if (!(d instanceof Element)) return false;
                if (d.getAttribute('data-state') !== 'open') return false;
                const st = window.getComputedStyle(d);
                const r = d.getBoundingClientRect();
                return (
                    r.width > 0 &&
                    r.height > 0 &&
                    st.display !== 'none' &&
                    st.visibility !== 'hidden' &&
                    Number(st.opacity || '1') > 0
                );
            };
            const drawers = Array.from(document.querySelectorAll('[data-testid="settings-drawer"]'));
            const candidates = drawers.filter(drawerOpenVisible);
            for (let i = candidates.length - 1; i >= 0; i -= 1) {
                const d = candidates[i];
                if (!d.querySelector('[data-testid="settings-panel-connection"]')) continue;
                const controls = d.querySelector('[data-testid="settings-connection-controls"]');
                if (!controls) continue;
                const kill = controls.querySelector('[data-testid="settings-offline-kill-btn"]');
                const connPanel = d.querySelector('[data-testid="settings-panel-connection"]');
                let roleGo = null;
                if (connPanel) {
                    const btns = Array.from(connPanel.querySelectorAll('button'));
                    roleGo = btns.find((b) => /go offline/i.test(b.textContent || '')) || null;
                }
                const el = kill || roleGo;
                if (!el) continue;
                const g = domGeomVis(el);
                return {
                    found: true,
                    match: kill ? 'settings-offline-kill-btn' : 'role-go-offline',
                    drawerDataState: d.getAttribute('data-state') || '',
                    ...g,
                };
            }
            return { found: false, present: false, domGeometryVisible: false, enabled: false, text: '' };
        })
