import { test, expect } from '@playwright/test';
import path from 'path';
import fs from 'fs';
import { pathToFileURL } from 'url';

const projectRoot = path.join(__dirname, '..');
const vaultPanelDistHtml = path.join(
  projectRoot,
  'packages',
  'modules',
  'vaultpanel-plus',
  'dist',
  'index.html'
);

test.describe('VaultPanel burn-in signal', () => {
  test('renders safe default state without live pod traffic', async ({ page }) => {
    test.skip(
      !fs.existsSync(vaultPanelDistHtml),
      'VaultPanel dist artifact required; run bridge-readiness prepare first.'
    );

    await page.goto(pathToFileURL(vaultPanelDistHtml).href, { waitUntil: 'domcontentloaded' });

    const burnIn = page.getByTestId('vaultpanel-burn-in-signal');
    await expect(burnIn).toBeVisible({ timeout: 15000 });

    await expect(burnIn).toContainText('OFFLINE');
    await expect(burnIn).toContainText('No live transport adapter. Burn-in signal is idle.');
    await expect(burnIn).toContainText('Signal count');
    await expect(burnIn).toContainText('Heartbeat count');
    await expect(burnIn.getByText('0', { exact: true })).toHaveCount(4);
  });
});

import http from 'http';
import fs from 'fs';
import path from 'path';

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
};

export type StaticDistServer = {
  baseUrl: string;
  close: () => Promise<void>;
};

export function startStaticDistServer(distDir: string): Promise<StaticDistServer> {
  return new Promise((resolve, reject) => {
    const root = path.resolve(distDir);
    const server = http.createServer((req, res) => {
      const requestPath = (req.url || '/').split('?')[0];
      const relativePath = requestPath === '/' ? '/index.html' : requestPath;
      const filePath = path.normalize(path.join(root, decodeURIComponent(relativePath)));

      if (!filePath.startsWith(root)) {
        res.writeHead(403);
        res.end();
        return;
      }

      fs.readFile(filePath, (error, data) => {
        if (error) {
          res.writeHead(404);
          res.end();
          return;
        }

        const contentType = MIME_TYPES[path.extname(filePath).toLowerCase()] || 'application/octet-stream';
        res.writeHead(200, { 'Content-Type': contentType });
        res.end(data);
      });
    });

    server.on('error', reject);
    server.listen(0, '127.0.0.1', () => {
      const address = server.address();
      const port = typeof address === 'object' && address ? address.port : 0;
      resolve({
        baseUrl: `http://127.0.0.1:${port}`,
        close: () =>
          new Promise((closeResolve, closeReject) => {
            server.close((closeError) => (closeError ? closeReject(closeError) : closeResolve()));
          }),
      });
    });
  });
}

import { test, expect } from '@playwright/test';
import path from 'path';
import fs from 'fs';
import { startStaticDistServer } from './helpers/staticDistServer';

const projectRoot = path.join(__dirname, '..');
const vaultPanelDistDir = path.join(projectRoot, 'packages', 'modules', 'vaultpanel-plus', 'dist');
const vaultPanelDistHtml = path.join(vaultPanelDistDir, 'index.html');

test.describe('VaultPanel burn-in signal', () => {
  test('renders safe default state without live pod traffic', async ({ page }) => {
    test.skip(
      !fs.existsSync(vaultPanelDistHtml),
      'VaultPanel dist artifact required; run bridge-readiness prepare first.'
    );

    const server = await startStaticDistServer(vaultPanelDistDir);
    try {
      await page.goto(`${server.baseUrl}/index.html`, { waitUntil: 'networkidle' });

      const burnIn = page.getByTestId('vaultpanel-burn-in-signal');
      await expect(burnIn).toBeVisible({ timeout: 15000 });

      await expect(burnIn).toContainText('OFFLINE');
      await expect(burnIn).toContainText('No live transport adapter. Burn-in signal is idle.');
      await expect(burnIn).toContainText('Signal count');
      await expect(burnIn).toContainText('Heartbeat count');
      await expect(burnIn.getByText('0', { exact: true })).toHaveCount(4);
    } finally {
      await server.close();
    }
  });
});
